src/scripts/lib/script-ref.ts:
/**
 * script-ref.ts — Gives each one-shot script in `src/scripts/` a
 * self-describing reference to its own identity, so workflow-authoring code
 * (`src/workflows/*.wac.ts`) never has to hand-type the script's deployed
 * path as a separate string.
 *
 * Call `defineScript<TArgs>(import.meta.url)` once at the top of a script
 * (right after its `Args` interface, if it has one) and export the result
 * as `ref`:
 *
 *   export interface FooArgs { ... }
 *   export const ref = defineScript<FooArgs>(import.meta.url);
 *
 * `import.meta.url` is populated by the runtime from the actual file being
 * executed/imported, so the derived path can never drift from the real
 * file -- a rename/move is automatically reflected. This replaces the old
 * "path-validation-only `import type * as Foo`" convention: importing `ref`
 * is a real VALUE import, which already fails `tsc --noEmit` (TS2307) the
 * same way a type-only import did if the script is renamed/deleted, while
 * additionally carrying the actual runtime path -- so `scriptCommand()` (see
 * `src/workflows/actions/script-call.ts`) needs no separate hand-typed path
 * string at all.
 *
 * `TArgs` (for scripts whose CLI flags are a flat named-args object, built
 * via `toArgv()`) is carried on `ScriptRef` purely as a phantom type -- never
 * populated at runtime -- so `scriptCommandWithArgs()` can type-check the
 * `args` object passed at each call site directly against it, with no
 * separate import of the named `Args` interface needed at the call site.
 */
import { basename } from "node:path";
import { fileURLToPath } from "node:url";

/** Where `build-dist.ts` places scripts inside a deployed `.github/`. */
const SCRIPTS_RUNTIME_ROOT = ".github/scripts";

export interface ScriptRef<TArgs = void> {
  /** Deployed runtime path, e.g. `.github/atoma/tools/scripts/foo.ts`. */
  readonly runtimePath: string;
  /**
   * Never populated -- a phantom marker so TypeScript treats `ScriptRef<A>`
   * and `ScriptRef<B>` as distinct types even though they're structurally
   * identical at runtime (both just `{ runtimePath }`).
   */
  readonly __argsType?: TArgs;
}

/**
 * Define a script's identity from its own `import.meta.url`. `TArgs` should
 * be the script's exported CLI-flags interface, e.g.
 * `defineScript<FooArgs>(import.meta.url)` -- omit it for scripts driven
 * purely by env vars, or with no external input at all.
 */
export function defineScript<TArgs = void>(importMetaUrl: string): ScriptRef<TArgs> {
  return { runtimePath: `${SCRIPTS_RUNTIME_ROOT}/${basename(fileURLToPath(importMetaUrl))}` };
}

src/workflows/actions/script-call.ts:
/**
 * script-call.ts — Type-safe(r) invocation of the one-shot TS scripts in
 * `src/scripts/` (deployed flat into `.github/atoma/tools/scripts/*.ts` by
 * `build-dist.ts`) from inside a workflow step's `run:` bash.
 *
 * Every call site used to hardcode the *deployed* path as a bare string --
 * `bun run .github/atoma/tools/scripts/foo.ts` -- with zero connection to
 * the actual script file, PLUS a separately hand-typed import specifier
 * paired next to it purely so a rename/delete would fail `tsc --noEmit`.
 * Two independent strings, nothing stopping them from silently mismatching.
 *
 * Now every call site imports the script's own `ref` (see
 * `../../scripts/lib/script-ref.ts`) -- a real value, derived from the
 * script's `import.meta.url`, so there is only ONE thing identifying the
 * script (the import itself) and the deployed path is never hand-typed at
 * all. `scriptCommand()`/`scriptCommandWithArgs()` just turn that `ref` (and,
 * for the latter, a typed `args` object checked directly against the
 * script's own `Args` interface) into the `bun run ...` command string.
 */
import { toArgv } from "../../scripts/lib/cli.ts";
import type { ScriptRef } from "../../scripts/lib/script-ref.ts";

/**
 * Build a `bun run <deployed-path> [argv...]` command for a script that
 * takes no CLI flags at all (env-driven, or none) -- or whose CLI shape
 * doesn't fit a flat named-args object (e.g. `get_config_value.ts`'s
 * positional `<path> [default]`, built with its own `buildArgv()`). Pass a
 * pre-built argv array for that second case.
 */
export function scriptCommand(ref: ScriptRef<void>, argv: readonly string[] = []): string {
  return argv.length > 0 ? `bun run ${ref.runtimePath} ${argv.join(" ")}` : `bun run ${ref.runtimePath}`;
}

/**
 * Build a `bun run <deployed-path> --flag "value" ...` command for a script
 * whose CLI flags are a flat named-args object. `args` is checked directly
 * against the script's own exported `Args` interface via `ref`'s type
 * parameter -- no separate import of that interface needed at the call site.
 *
 * `TArgs extends object` (not `extends Record<string, ...>`) because plain
 * named-property interfaces (e.g. `export interface FooArgs { repo: string }`)
 * have no index signature and don't structurally satisfy a `Record<...>`
 * constraint -- same reasoning as `CustomAction`'s `TWith` in `base.ts`.
 */
export function scriptCommandWithArgs<TArgs extends object>(ref: ScriptRef<TArgs>, args: TArgs): string {
  return scriptCommand(
    { runtimePath: ref.runtimePath },
    toArgv(args as Record<string, string | number | boolean | undefined>),
  );
}



